        public List<SubAccount> GetSubAccountList()
        {
            SubAccDAO dao = new SubAccDAO();

            DataTable dataTable = dao.Age_CustSubSel(CurrentSession.CustId);
            var subAccRows = dataTable.Rows;
            var subAccList = new List<SubAccount>();

            foreach (DataRow subAccRow in subAccRows)
            {
                subAccList.Add(new SubAccount(subAccRow));
            }

            return subAccList;
        }

