            SubAccDAO dao = new SubAccDAO();
            SubAccount subAccount = new SubAccount();

            DataTable dataTable = dao.Age_CustSubSelInfo(CurrentSession.CustId, subAccId);
            if (dataTable != null && dataTable.Rows.Count > 0)
